contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate <= 5000);
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ); if (__ESBMC_reverted()) return;
        assert(
            c.baseToken() == _baseToken &&
            c.nft() == _nft &&
            c.virtualBaseTokenReserves() == _virtualBaseTokenReserves &&
            c.virtualNftReserves() == _virtualNftReserves &&
            c.changeFee() == _changeFee &&
            c.feeRate() == _feeRate &&
            c.merkleRoot() == _merkleRoot &&
            c.useStolenNftOracle() == _useStolenNftOracle &&
            c.payRoyalties() == _payRoyalties
        );
    }

    receive() external payable {}
}

